fn split_word(w: Str, width: Int) -> List[Str] {
  return w.chars().chunks(width).map(fn(c) => c.join(""))
}

pub fn wrap(text: Str, width: Int) -> List[Str] {
  let words = text.split(" ").filter(fn(w) => w.len() > 0).flat_map(fn(w) => split_word(w, width))
  var lines: List[Str] = []
  var cur = ""
  for w in words {
    if cur == "" {
      cur = w
    } else if cur.len() + 1 + w.len() <= width {
      cur = cur + " " + w
    } else {
      lines = lines.push(cur)
      cur = w
    }
  }
  if cur != "" {
    lines = lines.push(cur)
  }
  return lines
}
